import { tags } from "typia";

/**
 * Logout request controlling session termination across the shopping mall
 * platform. This request provides granular control over the logout process,
 * supporting single-session termination or comprehensive logout across all user
 * devices and contexts while maintaining audit trails for security and
 * compliance purposes.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallLogoutRequest = {
  /**
   * JWT access token to be invalidated during the logout process. This token
   * will be permanently marked as invalid and removed from active session
   * management across the platform.
   */
  token: string &
    tags.Pattern<"^[A-Za-z0-9-_]+\\.[A-Za-z0-9-_]+\\.[A-Za-z0-9-_]+$">;

  /**
   * Flag indicating whether to terminate all active sessions for this user
   * across all devices and contexts. When true, invalidates all tokens and
   * sessions associated with the user account.
   */
  logoutAllDevices?: boolean | undefined;

  /**
   * Optional reason or note for the logout event. Used for audit logging,
   * user analytics, and troubleshooting session issues. Common reasons
   * include: 'user_action', 'security_concern', 'session_timeout'.
   */
  reason?: (string & tags.MaxLength<500>) | undefined;

  /**
   * Indicates whether to perform comprehensive session cleanup including
   * removing session artifacts, temporary data, and cached information
   * associated with this session. Enables more thorough session termination.
   */
  sessionCleanup?: boolean | undefined;
};
